Tool response:
Tool: update_reservation
Description: Update Reservation
Parameters:
    {
      "type": "object",
      "properties": {
        "id": {
          "type": "integer",
          "description": "Internal ID of the reservation to update",
          "title": "Id"
        },
        "new_check_out_date": {
          "type": "string",
          "format": "date",
          "title": "New Check Out Date"
        },
        "new_payment_method_id": {
          "type": "integer",
          "title": "New Payment Method Id"
        }
      },
      "required": [
        "id",
        "new_check_out_date",
        "new_payment_method_id"
      ]
    }

Tool response:
Tool: list_payment_methods
Description: List Payment Methods
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "ID of the user whose payment methods are to be retrieved",
          "title": "User Id"
        }
      },
      "required": [
        "user_id"
      ]
    }
